COMMENT ON TABLE harmless_receipt IS '无害化处理回执：化制/销毁判定头只的处理闭环凭证，与判定数勾稽';
COMMENT ON COLUMN harmless_receipt.batch_id IS '所属屠宰批次主键';
COMMENT ON COLUMN harmless_receipt.receipt_no IS '回执编号，批次内唯一';
