31	import org.springframework.transaction.annotation.Transactional;
32	
33	/**
34	 * 风险抽检服务：宰前检疫合格后绑定合成风险等级并冻结抽检清单，逐只结果联动专项隔离与出厂门禁。
35	 *
36	 * <p>并发控制：每个写事务先 {@code SELECT ... FOR UPDATE} 锁定批次主行，再锁风险绑定行，
37	 * 与 {@link BatchService} 出厂核销同序加锁，保证风险变更、最后结果、阳性与出厂核销两两互斥，
38	 * 不会出现已放行但漏检的批次。业务失败整体回滚，幂等登记同事务因此不占键。
39	 */
40	@org.springframework.stereotype.Service
41	public class RiskService {
42	
43	    private final BatchRepository batchRepo;
44	    private final RiskRepository riskRepo;
45	    private final Clock clock;
46	    private final ObjectMapper objectMapper;
47	    private final IdempotentExecutor idempotency;
48	
49	    public RiskService(BatchRepository batchRepo, RiskRepository riskRepo, Clock clock,
50	                       ObjectMapper objectMapper, IdempotentExecutor idempotency) {
51	        this.batchRepo = batchRepo;
52	        this.riskRepo = riskRepo;
53	        this.clock = clock;
54	        this.objectMapper = objectMapper;
55	        this.idempotency = idempotency;
56	    }
57	
58	    // ---------- 风险绑定 ----------
59	
60	    /** 绑定合成风险等级并冻结首份抽检清单（幂等）。 */
61	    @Transactional
62	    public RiskChecklistResponse bind(String batchNo, RiskBindRequest req) {
63	        return idempotency.run("risk-bind", req.requestId(), req, RiskChecklistResponse.class,
64	                () -> doBind(batchNo, req));
65	    }
66	
67	    private RiskChecklistResponse doBind(String batchNo, RiskBindRequest req) {
68	        String occurredAt = parseOccurredAt(req.occurredAt());
69	        RiskLevel level = parseLevel(req.level());
70	        List<String> declared = normalizeDeclared(req.declaredHeadNos());
71	        BatchRow batch = lockAndReload(batchNo);
72	        if (BatchStatus.RELEASED.name().equals(batch.status())) {
73	            return lateChecklist(batch, "LATE_RISK_BIND",
74	                    "核销后迟到风险绑定：等级 " + level.name() + "，规则版本 " + req.ruleVersion(),
75	                    req.ruleVersion(), level.name(), 0, List.of(), declared);
76	        }
77	        if (BatchStatus.DECLARED.name().equals(batch.status())) {
78	            throw ApiException.unprocessable("批次宰前检疫尚未合格，不允许绑定风险等级");
79	        }
80	        if (riskRepo.findBinding(batch.id()).isPresent()) {
81	            throw ApiException.conflict("批次已绑定风险等级，同一批次只允许一个当前风险绑定");
82	        }
83	        if (req.expectedVersion() != 0) {
84	            throw ApiException.conflict("首次风险绑定 expectedVersion 须为 0");
85	        }
86	        verifyDeclaredMatchesLedger(batch.id(), declared);
87	
88	        List<String> samples = pickSamples(declared, level);
89	        String now = occurredAt;
90	        riskRepo.insertChecklist(batch.id(), 1L, "INITIAL", level.name(), req.ruleVersion(), "OPEN",
91	                toJson(declared), toJson(samples), occurredAt);
92	        riskRepo.insertBinding(batch.id(), 1, level.name(), req.ruleVersion(), 1L, now);
93	        riskRepo.insertChangeEvent(batch.id(), "BIND", null, level.name(), null, req.ruleVersion(),
94	                1L, 0, 1, occurredAt);
95	        return new RiskChecklistResponse(batchNo, 1, 1L, "INITIAL", level.name(), req.ruleVersion(),
96	                "OPEN", samples, declared, false, false, false);
97	    }
98	
99	    // ---------- 风险等级变更 ----------
100	
101	    /** 风险等级变更：未完成清单提高等级原子扩充；已完成清单另开补充清单；降低/同级拒绝（幂等）。 */
102	    @Transactional
103	    public RiskChecklistResponse changeLevel(String batchNo, RiskChangeRequest req) {
104	        return idempotency.run("risk-change", req.requestId(), req, RiskChecklistResponse.class,
105	                () -> doChangeLevel(batchNo, req));
106	    }
107	
108	    private RiskChecklistResponse doChangeLevel(String batchNo, RiskChangeRequest req) {
109	        String occurredAt = parseOccurredAt(req.occurredAt());
110	        RiskLevel level = parseLevel(req.level());
111	        List<String> declared = normalizeDeclared(req.declaredHeadNos());
112	        BatchRow batch = lockAndReload(batchNo);
113	        if (BatchStatus.RELEASED.name().equals(batch.status())) {
114	            RiskBindingRow current = riskRepo.findBinding(batch.id()).orElse(null);
115	            return lateChecklist(batch, "LATE_RISK_CHANGE",
116	                    "核销后迟到风险变更：等级 " + level.name() + "，规则版本 " + req.ruleVersion(),
117	                    req.ruleVersion(), level.name(),
118	                    current == null ? 0L : current.currentSequenceNo(), List.of(), declared);
119	        }
120	        RiskBindingRow binding = mustFindBinding(batch);
121	        if (req.expectedVersion() != binding.version()) {
122	            throw ApiException.conflict("风险版本不匹配：expectedVersion=" + req.expectedVersion()
123	                    + "，当前版本=" + binding.version());
124	        }
125	        verifyDeclaredMatchesLedger(batch.id(), declared);
126	        RiskLevel currentLevel = parseLevel(binding.level());
127	        if (level.rank() <= currentLevel.rank()) {
128	            throw ApiException.unprocessable("只允许提高风险等级；等级降低不缩减冻结清单，同级无变化拒绝受理");
129	        }
130	        ChecklistRow current = mustFindChecklist(batch.id(), binding.currentSequenceNo());
131	        if ("OPEN".equals(current.status())) {
132	            // 原子扩充：沿用原清单序号，既有逐只结果原样保留，仅扩大冻结抽检集合与风险规则。
133	            List<String> expanded = pickSamples(declared, level);
134	            int updated = riskRepo.expandChecklist(batch.id(), current.sequenceNo(), level.name(),
135	                    req.ruleVersion(), toJson(expanded), occurredAt);
136	            if (updated == 0) {
137	                throw ApiException.conflict("并发冲突：当前清单状态已变化，原子扩充失败");
138	            }
139	            int newVersion = binding.version() + 1;
140	            updateBindingOrFail(batch.id(), binding, newVersion, level.name(), req.ruleVersion(),
141	                    current.sequenceNo(), occurredAt);
142	            riskRepo.insertChangeEvent(batch.id(), "EXPAND", binding.level(), level.name(),
143	                    binding.ruleVersion(), req.ruleVersion(), current.sequenceNo(),
144	                    binding.version(), newVersion, occurredAt);
145	            GateState gate = gateState(batch.id());
146	            return new RiskChecklistResponse(batchNo, newVersion, current.sequenceNo(), "EXPANDED",
147	                    level.name(), req.ruleVersion(), "OPEN", expanded, declared,
148	                    gate.completed(), gate.quarantine(), false);
149	        }
150	        // 当前清单已完成：不可改，另开补充清单并再次锁出厂。
151	        long newSequenceNo = current.sequenceNo() + 1;
152	        List<String> samples = pickSamples(declared, level);
153	        riskRepo.insertChecklist(batch.id(), newSequenceNo, "SUPPLEMENTARY", level.name(),
154	                req.ruleVersion(), "OPEN", toJson(declared), toJson(samples), occurredAt);
155	        int newVersion = binding.version() + 1;
156	        updateBindingOrFail(batch.id(), binding, newVersion, level.name(), req.ruleVersion(),
157	                newSequenceNo, occurredAt);
158	        riskRepo.insertChangeEvent(batch.id(), "SUPPLEMENT", binding.level(), level.name(),
159	                binding.ruleVersion(), req.ruleVersion(), newSequenceNo,
160	                binding.version(), newVersion, occurredAt);
161	        return new RiskChecklistResponse(batchNo, newVersion, newSequenceNo, "SUPPLEMENTARY",
162	                level.name(), req.ruleVersion(), "OPEN", samples, declared, false,
163	                gateState(batch.id()).quarantine(), false);
164	    }
165	
166	    // ---------- 逐只抽检结果 ----------
167	
168	    /** 逐只提交抽检结果：清单外拒绝、同结果重复无新记录、异结果冲突；阳性联动专项隔离（幂等）。 */
169	    @Transactional
170	    public RiskResultResponse submitResult(String batchNo, RiskResultRequest req) {
171	        return idempotency.run("risk-result", req.requestId(), req, RiskResultResponse.class,
172	                () -> doSubmitResult(batchNo, req));
173	    }
174	
175	    private RiskResultResponse doSubmitResult(String batchNo, RiskResultRequest req) {
176	        String occurredAt = parseOccurredAt(req.occurredAt());
177	        String result = parseResult(req.result());
178	        BatchRow batch = lockAndReload(batchNo);
179	        if (BatchStatus.RELEASED.name().equals(batch.status())) {
180	            batchRepo.insertLateEvent(batch.id(), "LATE_RISK_RESULT",
181	                    "核销后迟到抽检结果：头只 " + req.headNo() + "，结果 " + result, now());
182	            RiskBindingRow binding = riskRepo.findBinding(batch.id()).orElse(null);
183	            GateState gate = binding == null ? GateState.none() : gateState(batch.id());
184	            return new RiskResultResponse(batchNo, binding == null ? 0 : binding.version(),
185	                    binding == null ? 0L : binding.currentSequenceNo(), req.headNo(), result, false,
186	                    gate.completed(), gate.completed(), gate.allNegative(), gate.quarantine(), true);
187	        }
188	        RiskBindingRow binding = mustFindBinding(batch);
189	        if (req.expectedVersion() != binding.version()) {
190	            throw ApiException.conflict("风险版本不匹配：expectedVersion=" + req.expectedVersion()
191	                    + "，当前版本=" + binding.version());
192	        }
193	        long sequenceNo = binding.currentSequenceNo();
194	        ChecklistRow checklist = mustFindChecklist(batch.id(), sequenceNo);
195	        List<String> frozen = fromJson(checklist.frozenSamples());
196	        if (!frozen.contains(req.headNo())) {
197	            throw ApiException.unprocessable("头只不在当前抽检清单（序号 " + sequenceNo
198	                    + "）冻结范围内，清单外结果拒绝：" + req.headNo());
199	        }
200	        Optional<SampleRow> existing = riskRepo.findSamples(batch.id(), sequenceNo).stream()
201	                .filter(s -> s.headNo().equals(req.headNo())).findFirst();
202	        if (existing.isPresent()) {
203	            if (!existing.get().result().equals(result)) {
204	                throw ApiException.conflict("头只 " + req.headNo() + " 已登记结果 "
205	                        + existing.get().result() + "，异结果 " + result + " 冲突");
206	            }
207	            // 同结果重复：无新记录、版本不增加，返回当前门禁状态。
208	            GateState gate = gateState(batch.id());
209	            return new RiskResultResponse(batchNo, binding.version(), sequenceNo, req.headNo(), result,
210	                    true, gate.isChecklistCompleted(sequenceNo), gate.completed(), gate.allNegative(),
211	                    gate.quarantine(), false);
212	        }
213	        try {
214	            riskRepo.insertSample(batch.id(), sequenceNo, req.headNo(), result, occurredAt);
215	        } catch (org.springframework.dao.DuplicateKeyException e) {
216	            // 同头只并发插入：唯一约束兜底，重读既有结果区分同结果重复与异结果冲突。
217	            SampleRow concurrent = riskRepo.findSamples(batch.id(), sequenceNo).stream()
218	                    .filter(s -> s.headNo().equals(req.headNo())).findFirst()
219	                    .orElseThrow(() -> e);
220	            if (!concurrent.result().equals(result)) {
221	                throw ApiException.conflict("头只 " + req.headNo() + " 已登记结果 "
222	                        + concurrent.result() + "，异结果 " + result + " 并发冲突");
223	            }
224	            GateState gate = gateState(batch.id());
225	            return new RiskResultResponse(batchNo, binding.version(), sequenceNo, req.headNo(), result,
226	                    true, gate.isChecklistCompleted(sequenceNo), gate.completed(), gate.allNegative(),
227	                    gate.quarantine(), false);
228	        }
229	        if ("POSITIVE".equals(result)) {
230	            // 条件流转：任一阳性整批专项隔离；RELEASED 终态不受影响（迟到分支已先行处理）。
231	            riskRepo.markSpecialQuarantine(batch.id());
232	        }
233	        GateState afterInsert = gateState(batch.id());
234	        if (afterInsert.isChecklistCompleted(sequenceNo) && "OPEN".equals(checklist.status())) {
235	            riskRepo.completeChecklist(batch.id(), sequenceNo, occurredAt);
236	        }
237	        GateState gate = gateState(batch.id());
238	        int newVersion = binding.version() + 1;
239	        updateBindingOrFail(batch.id(), binding, newVersion, binding.level(), binding.ruleVersion(),
240	                sequenceNo, occurredAt);
241	        return new RiskResultResponse(batchNo, newVersion, sequenceNo, req.headNo(), result, false,
242	                gate.isChecklistCompleted(sequenceNo), gate.completed(), gate.allNegative(),
243	                gate.quarantine(), false);
244	    }
245	
246	    // ---------- 清单及隔离原因查询 ----------
247	
248	    /** 清单及隔离原因查询：未绑定风险的批次返回 controlled=false 的空清单视图。 */
249	    @Transactional(readOnly = true)
250	    public RiskSummaryView getSummary(String batchNo) {
251	        BatchRow batch = batchRepo.findBatchByNo(batchNo)
252	                .orElseThrow(() -> ApiException.notFound("批次不存在：" + batchNo));
253	        Optional<RiskBindingRow> bindingOpt = riskRepo.findBinding(batch.id());
254	        List<ChecklistRow> checklists = riskRepo.findChecklists(batch.id());
255	        List<SampleRow> allSamples = riskRepo.findAllSamples(batch.id());
256	        Map<Long, List<SampleRow>> samplesBySeq = new LinkedHashMap<>();
257	        for (SampleRow sample : allSamples) {
258	            samplesBySeq.computeIfAbsent(sample.sequenceNo(), k -> new ArrayList<>()).add(sample);
259	        }
260	        List<RiskSummaryView.ChecklistView> checklistViews = new ArrayList<>();
261	        List<RiskSummaryView.QuarantineReasonView> reasons = new ArrayList<>();
262	        boolean anyPositive = false;
263	        boolean allFrozenHaveResults = true;
264	        for (ChecklistRow checklist : checklists) {
265	            List<String> frozen = fromJson(checklist.frozenSamples());
266	            Map<String, SampleRow> byHead = new LinkedHashMap<>();
267	            for (SampleRow sample : samplesBySeq.getOrDefault(checklist.sequenceNo(), List.of())) {
268	                byHead.put(sample.headNo(), sample);
269	            }
270	            List<RiskSummaryView.SampleView> sampleViews = new ArrayList<>();
271	            for (String headNo : frozen) {
272	                SampleRow sample = byHead.get(headNo);
273	                sampleViews.add(new RiskSummaryView.SampleView(headNo,
274	                        sample == null ? null : sample.result(),
275	                        sample == null ? null : sample.submittedAt()));
276	                if (sample == null) {
277	                    allFrozenHaveResults = false;
278	                } else if ("POSITIVE".equals(sample.result())) {
279	                    anyPositive = true;
280	                    reasons.add(new RiskSummaryView.QuarantineReasonView(checklist.sequenceNo(),
281	                            headNo, "POSITIVE", sample.submittedAt(), checklist.level(),
282	                            checklist.ruleVersion()));
283	                }
284	            }
285	            checklistViews.add(new RiskSummaryView.ChecklistView(checklist.sequenceNo(),
286	                    checklist.kind(), checklist.level(), checklist.ruleVersion(), checklist.status(),
287	                    fromJson(checklist.frozenDeclared()), sampleViews, checklist.createdAt(),
288	                    checklist.completedAt()));
289	        }
290	        if (bindingOpt.isEmpty()) {
291	            return new RiskSummaryView(batchNo, null, null, null, null, false, false, false, false,
292	                    checklistViews, reasons);
293	        }
294	        RiskBindingRow binding = bindingOpt.get();
295	        boolean quarantine = BatchStatus.SPECIAL_QUARANTINE.name().equals(batch.status()) || anyPositive;
296	        return new RiskSummaryView(batchNo, binding.version(), binding.currentSequenceNo(),
297	                binding.level(), binding.ruleVersion(), allFrozenHaveResults && !checklists.isEmpty(),
298	                allFrozenHaveResults && !checklists.isEmpty() && !anyPositive, quarantine, true,
299	                checklistViews, reasons);
300	    }
301	
302	    // ---------- 出厂门禁（供 BatchService 复用） ----------
303	
304	    /**
305	     * 受控批次出厂门禁：存在风险绑定时，全部清单完成且全部样本阴性才放行抽检门禁；
306	     * 任一阳性或存在未出结果样本即拒绝。调用方须已持有批次行锁。
307	     */
308	    public void assertReleaseGate(long batchId) {
309	        Optional<RiskBindingRow> binding = riskRepo.findBinding(batchId);
310	        if (binding.isEmpty()) {
311	            return;
312	        }
313	        GateState gate = gateState(batchId);
314	        if (gate.quarantine()) {
315	            throw ApiException.conflict("抽检发现阳性，整批专项隔离，受控出厂拒绝");
316	        }
317	        if (!gate.completed()) {
318	            throw ApiException.conflict("风险抽检尚未完成，受控出厂门禁未解除");
319	        }
320	    }
321	
322	    // ---------- 内部：门禁状态复算 ----------
323	
324	    /** 由冻结清单与逐只结果复算的门禁状态。 */
325	    private record GateState(boolean completed, boolean allNegative, boolean quarantine,
326	                             Map<Long, Boolean> checklistCompleted) {
327	        static GateState none() {
328	            return new GateState(false, true, false, Map.of());
329	        }
330	
331	        /** 指定清单是否全部冻结样本均有结果。 */
332	        boolean isChecklistCompleted(long sequenceNo) {
333	            return checklistCompleted.getOrDefault(sequenceNo, false);
334	        }
335	    }
336	
337	    private GateState gateState(long batchId) {
338	        List<ChecklistRow> checklists = riskRepo.findChecklists(batchId);
339	        List<SampleRow> samples = riskRepo.findAllSamples(batchId);
340	        Map<Long, Map<String, String>> bySeq = new LinkedHashMap<>();
341	        for (SampleRow sample : samples) {
342	            bySeq.computeIfAbsent(sample.sequenceNo(), k -> new LinkedHashMap<>())
343	                    .put(sample.headNo(), sample.result());
344	        }
345	        boolean allCompleted = !checklists.isEmpty();
346	        boolean allNegative = true;
347	        Map<Long, Boolean> perChecklist = new LinkedHashMap<>();
348	        for (ChecklistRow checklist : checklists) {
349	            List<String> frozen = fromJson(checklist.frozenSamples());
350	            Map<String, String> results = bySeq.getOrDefault(checklist.sequenceNo(), Map.of());
351	            boolean checklistDone = frozen.stream().allMatch(results::containsKey);
352	            perChecklist.put(checklist.sequenceNo(), checklistDone);
353	            allCompleted &= checklistDone;
354	            for (String headNo : frozen) {
355	                if ("POSITIVE".equals(results.get(headNo))) {
356	                    allNegative = false;
357	                }
358	            }
359	        }
360	        boolean quarantine = !allNegative;
361	        return new GateState(allCompleted, allNegative, quarantine, perChecklist);
362	    }
363	
364	    // ---------- 内部：迟到告警 ----------
365	
366	    private RiskChecklistResponse lateChecklist(BatchRow batch, String eventType, String detail,
367	                                                String ruleVersion, String level, long sequenceNo,
368	                                                List<String> sampled, List<String> declared) {
369	        String now = now();
370	        batchRepo.insertLateEvent(batch.id(), eventType, detail, now);
371	        Optional<RiskBindingRow> binding = riskRepo.findBinding(batch.id());
372	        GateState gate = binding.map(b -> gateState(batch.id())).orElse(GateState.none());
373	        int version = binding.map(RiskBindingRow::version).orElse(0);
374	        long seq = sequenceNo != 0L ? sequenceNo : binding.map(RiskBindingRow::currentSequenceNo).orElse(0L);
375	        return new RiskChecklistResponse(batch.batchNo(), version, seq, "LATE", level, ruleVersion,
376	                "LATE", sampled, declared, gate.completed(), gate.quarantine(), true);
377	    }
378	
379	    // ---------- 内部：工具 ----------
380	
381	    /** 锁定批次主行并重新读取最新状态，保证与出厂核销等竞争事务互斥后再判定。 */
382	    private BatchRow lockAndReload(String batchNo) {
383	        BatchRow batch = batchRepo.findBatchByNo(batchNo)
384	                .orElseThrow(() -> ApiException.notFound("批次不存在：" + batchNo));
385	        batchRepo.lockBatch(batch.id());
386	        return batchRepo.findBatchByNo(batchNo).orElseThrow();
387	    }
388	
389	    private RiskBindingRow mustFindBinding(BatchRow batch) {
390	        return riskRepo.findBindingForUpdate(batch.id())
391	                .orElseThrow(() -> ApiException.notFound("批次尚未绑定风险等级：" + batch.batchNo()));
392	    }
393	
394	    private ChecklistRow mustFindChecklist(long batchId, long sequenceNo) {
395	        return riskRepo.findChecklist(batchId, sequenceNo)
396	                .orElseThrow(() -> ApiException.notFound("抽检清单不存在：序号 " + sequenceNo));
397	    }
398	
399	    private void updateBindingOrFail(long batchId, RiskBindingRow binding, int newVersion, String level,
400	                                     String ruleVersion, long currentSequenceNo, String now) {
401	        int updated = riskRepo.updateBinding(batchId, binding.version(), newVersion, level,
402	                ruleVersion, currentSequenceNo, now);
403	        if (updated == 0) {
404	            throw ApiException.conflict("并发冲突：风险版本已被其他请求变更");
405	        }
406	    }
407	
408	    /** 申报集合校验：与头只台账集合恰等（不依赖客户端顺序），不一致业务拒绝。 */
409	    private void verifyDeclaredMatchesLedger(long batchId, List<String> declaredSorted) {
410	        Set<String> ledger = new LinkedHashSet<>();
411	        for (HeadRow head : batchRepo.findHeads(batchId)) {
412	            ledger.add(head.headNo());
413	        }
414	        if (!ledger.equals(new LinkedHashSet<>(declaredSorted))) {
415	            throw ApiException.unprocessable("申报头只集合与头只台账不一致，拒绝冻结清单");
416	        }
417	    }
418	
419	    /** 按头只编号字典序取前 ceil(总数×比例) 只且至少 1 只。 */
420	    private List<String> pickSamples(List<String> declaredSorted, RiskLevel level) {
421	        int size = level.sampleSize(declaredSorted.size());
422	        return List.copyOf(declaredSorted.subList(0, Math.min(size, declaredSorted.size())));
423	    }
424	
425	    private List<String> normalizeDeclared(List<String> headNos) {
426	        Set<String> distinct = new LinkedHashSet<>();
427	        for (String headNo : headNos) {
428	            if (!distinct.add(headNo)) {
429	                throw ApiException.badRequest("申报头只编号重复：" + headNo);
430	            }
431	        }
432	        List<String> sorted = new ArrayList<>(distinct);
433	        sorted.sort(String::compareTo);
434	        return List.copyOf(sorted);
435	    }
436	
437	    private RiskLevel parseLevel(String level) {
438	        try {
439	            return RiskLevel.valueOf(level);
440	        } catch (Exception e) {
441	            throw ApiException.badRequest("未知风险等级：" + level + "，支持 NORMAL/TIGHTENED");
442	        }
443	    }
444	
445	    private String parseResult(String result) {
446	        if ("NEGATIVE".equals(result) || "POSITIVE".equals(result)) {
447	            return result;
448	        }
449	        throw ApiException.badRequest("未知抽检结果：" + result + "，支持 NEGATIVE/POSITIVE");
450	    }
451	
452	    private String parseOccurredAt(String occurredAt) {
453	        try {
454	            return Instant.parse(occurredAt).toString();
455	        } catch (Exception e) {
456	            throw ApiException.badRequest("occurredAt 须为 UTC ISO-8601 时刻：" + occurredAt);
457	        }
458	    }
459	
460	    private String toJson(List<String> values) {
461	        try {
462	            return objectMapper.writeValueAsString(values);
463	        } catch (Exception e) {
464	            throw new IllegalStateException("冻结集合序列化失败", e);
465	        }
466	    }
467	
468	    private List<String> fromJson(String json) {
469	        try {
470	            return objectMapper.readValue(json,
471	                    objectMapper.getTypeFactory().constructCollectionType(List.class, String.class));
472	        } catch (Exception e) {
473	            throw new IllegalStateException("冻结集合反序列化失败", e);
474	        }
475	    }
476	
477	    private String now() {
478	        return Instant.now(clock).toString();
479	    }
480	}
